			NpcID.TOA_WARDEN_TUMEKEN_PHASE1_INACTIVE, NpcID.TOA_WARDEN_TUMEKEN_PHASE1,
			NpcID.TOA_WARDEN_TUMEKEN_PHASE2_MAGE, NpcID.TOA_WARDEN_TUMEKEN_PHASE2_RANGE, NpcID.TOA_WARDEN_TUMEKEN_PHASE2_EXPOSED,
			NpcID.TOA_WARDEN_TUMEKEN_PHASE3_INACTIVE, NpcID.TOA_WARDEN_TUMEKEN_PHASE3, NpcID.TOA_WARDEN_TUMEKEN_PHASE3_CHARGING,
			NpcID.TOA_WARDEN_P3_DEATH_TUMEKEN);
		endsEncounter(NpcID.TOA_WARDEN_ELIDINIS_PHASE3, NpcID.TOA_WARDEN_ELIDINIS_PHASE3_CHARGING, NpcID.TOA_WARDEN_P3_DEATH_ELIDINIS,
			NpcID.TOA_WARDEN_TUMEKEN_PHASE3, NpcID.TOA_WARDEN_TUMEKEN_PHASE3_CHARGING, NpcID.TOA_WARDEN_P3_DEATH_TUMEKEN);
	}

	private Encounters()
	{
	}

	private static void shared(String encounter, String label, int... ids)
	{
		Member m = new Member(encounter, label, true);
		for (int id : ids)
		{
			MEMBERS.put(id, m);
		}
	}

	/** True for encounters won once every member that appeared has died. */
	static boolean allSeenMustDie(String encounter)
	{
		return ALL_SEEN.contains(encounter);
	}

	private static void member(String encounter, String label, boolean required, int... ids)
	{
		Member m = new Member(encounter, label, false);
		for (int id : ids)
		{
			MEMBERS.put(id, m);
		}
		Set<String> required0 = REQUIRED.computeIfAbsent(encounter, e -> new LinkedHashSet<>());
		if (required)
		{
			required0.add(label);
		}
	}

	private static void endsEncounter(int... ids)
	{
		for (int id : ids)
		{
			FINAL_FORMS.add(id);
		}
	}

	/** True if this form dying ends its encounter by itself (e.g. a Warden in phase 3). */
	static boolean endsEncounter(int npcId)
	{
		return FINAL_FORMS.contains(npcId);
	}

	/** This NPC's place in an encounter, or null if it isn't part of one. */
	static Member member(int npcId)
	{
		return MEMBERS.get(npcId);
	}

	/** True once every member that must die for this encounter has died. */
	static boolean isComplete(String encounter, Collection<String> deadMembers)
	{
		Set<String> required = REQUIRED.get(encounter);
		return required != null && !required.isEmpty() && deadMembers.containsAll(required);
	}
}

package com.bosshittracker;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * All saved data, keyed by boss name. Stored as JSON per RuneScape account.
 */
public class HitData
{
	/** Format version, used to run one-time upgrades of older saved data. */
	int version;
	Map<String, BossStats> bosses = new LinkedHashMap<>();
}

package com.bosshittracker;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Your hits on a single boss kill, grouped by weapon. When you were in a party, also each
 * player's hits grouped by weapon.
 */
public class KillRecord
{
	/** Name used for damage from players who weren't sharing hits (not in the party, or no plugin). */
	static final String OTHER_PLAYERS = "Other players";
	static final String UNKNOWN_WEAPON = "Unknown weapon";

	long timestamp;
	long durationMs;
	/** True when the boss wasn't killed (you or your team failed, left, or it reset). */
	boolean failed;
	/** Another player also damaged the boss, so the kill time isn't a solo time. */
	boolean othersHelped;
	Map<String, WeaponStats> weapons = new LinkedHashMap<>();
	/** Player name -> weapon -> stats. Only kept for kills with other players in them; null otherwise. */
	Map<String, Map<String, WeaponStats>> players;
	/** Phase label -> your hits in that phase. Only kept for multi-stage bosses; null otherwise. */
	Map<String, PhaseStats> phases;
	/** Target -> your hits on it, for bosses made of several NPCs (e.g. the Dagon'hai Trio); null otherwise. */
	Map<String, PhaseStats> targets;

	/** Used by Gson when loading saved data. */
	@SuppressWarnings("unused")
	KillRecord()
	{
	}

	KillRecord(long timestamp)
	{
		this.timestamp = timestamp;
	}

	void addHit(String weapon, int amount)
	{
		weapons.computeIfAbsent(weapon, w -> new WeaponStats()).addHit(amount);
	}

	/** A new attack with this weapon began (its first hit). It counts as missed until one of its hits does damage. */
	void startAttack(String weapon)
	{
		WeaponStats w = weapons.computeIfAbsent(weapon, k -> new WeaponStats());
		w.attacks++;
		w.missedAttacks++;
	}

	/** One of the current attack's hits did damage. */
	void attackLanded(String weapon)
	{
		WeaponStats w = weapons.get(weapon);
		if (w != null && w.missedAttacks > 0)
		{
			w.missedAttacks--;
		}
	}

	void addPlayerHit(String player, String weapon, int amount)
	{
		if (players == null)
		{
			players = new LinkedHashMap<>();
		}
		players.computeIfAbsent(player, p -> new LinkedHashMap<>())
			.computeIfAbsent(weapon, w -> new WeaponStats())
			.addHit(amount);
	}

	void addPhaseHit(String phase, int amount, long now)
	{
		if (phases == null)
		{
			phases = new LinkedHashMap<>();
		}
		phases.computeIfAbsent(phase, p -> new PhaseStats()).addHit(amount, now);
	}

	void addTargetHit(String target, int amount, long now)
	{
		if (targets == null)
		{
			targets = new LinkedHashMap<>();
		}
		targets.computeIfAbsent(target, t -> new PhaseStats()).addHit(amount, now);
	}

	/** Your hits per target for multi-NPC bosses, or an empty map. */
	public Map<String, PhaseStats> getTargets()
	{
		return targets == null ? new LinkedHashMap<>() : targets;
	}

	/** Your hits per phase for multi-stage bosses, or an empty map. */
	public Map<String, PhaseStats> getPhases()
	{
		return phases == null ? new LinkedHashMap<>() : phases;
	}

	/** Damage from players who weren't sharing, where only totals are known. */
	void addOtherPlayers(int hits, long damage)
	{
		if (players == null)
		{
			players = new LinkedHashMap<>();
		}
		WeaponStats w = players.computeIfAbsent(OTHER_PLAYERS, p -> new LinkedHashMap<>())
			.computeIfAbsent(UNKNOWN_WEAPON, k -> new WeaponStats());
		w.hits += hits;
		w.damage += damage;
	}

	public long getTimestamp()
	{
		return timestamp;
	}

	public long getDurationMs()
	{
		return durationMs;
	}

	public boolean isFailed()
	{
		return failed;
	}

	public Map<String, WeaponStats> getWeapons()
	{
		return weapons == null ? new LinkedHashMap<>() : weapons;
	}

	/** Each player's hits by weapon, or an empty map for solo kills. */
	public Map<String, Map<String, WeaponStats>> getPlayers()
	{
		return players == null ? new LinkedHashMap<>() : players;
	}

	/** True when this kill has damage from anyone besides you. */
	public boolean hasOtherPlayers()
	{
		return players != null && players.size() > 1;
	}

	static long totalDamage(Map<String, WeaponStats> weapons)
	{
		long total = 0;
		for (WeaponStats w : weapons.values())
		{
			total += w.damage;
		}
		return total;
	}

	static int totalHits(Map<String, WeaponStats> weapons)
	{
		int total = 0;
		for (WeaponStats w : weapons.values())
		{
			total += w.hits;
		}
		return total;
	}

	public int getTotalHits()
	{
		return totalHits(getWeapons());
	}

	public long getTotalDamage()
	{
		return totalDamage(getWeapons());
	}

	/** Damage from everyone in the kill (you, party members and other players). */
	public long getEveryoneDamage()
	{
		if (!hasOtherPlayers())
		{
			return getTotalDamage();
		}
		long total = 0;
		for (Map<String, WeaponStats> w : players.values())
		{
			total += totalDamage(w);
		}
		return total;
	}

	KillRecord copy()
	{
		KillRecord c = new KillRecord(timestamp);
		c.durationMs = durationMs;
		c.failed = failed;
		c.othersHelped = othersHelped;
		c.weapons = copyWeapons(getWeapons());
		if (phases != null)
		{
			c.phases = new LinkedHashMap<>();
			for (Map.Entry<String, PhaseStats> e : phases.entrySet())
			{
				c.phases.put(e.getKey(), e.getValue().copy());
			}
		}
		if (targets != null)
		{
			c.targets = new LinkedHashMap<>();
			for (Map.Entry<String, PhaseStats> e : targets.entrySet())
			{
				c.targets.put(e.getKey(), e.getValue().copy());
			}
		}
		if (players != null)
		{
			c.players = new LinkedHashMap<>();
			for (Map.Entry<String, Map<String, WeaponStats>> e : players.entrySet())
			{
				c.players.put(e.getKey(), copyWeapons(e.getValue()));
			}
		}
		return c;
	}

	private static Map<String, WeaponStats> copyWeapons(Map<String, WeaponStats> weapons)
	{
		Map<String, WeaponStats> c = new LinkedHashMap<>();
		for (Map.Entry<String, WeaponStats> e : weapons.entrySet())
		{
			c.put(e.getKey(), e.getValue().copy());
		}
		return c;
	}
}

package com.bosshittracker;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Weapons whose single attack (or special attack) shows up as several hitsplats on one target,
 * e.g. the Scythe of Vitur's three hits or Dragon claws' four. For accuracy, those hits count as one attack.
 * Based on the OSRS Wiki's multi-hit weapons and special attacks lists.
 */
final class MultiHit
{
	/**
	 * Lower-case part of the weapon name (every version contains it, e.g. "Holy Scythe of Vitur",
	 * "Torag's hammers 75") -> how many game ticks after an attack's first hit its other hits can land.
	 */
	private static final Map<String, Integer> WEAPONS = new LinkedHashMap<>();

	static
	{
		// Normal attacks that hit more than once
		window(1, "scythe of vitur", "dual macuahuitl", "tonalztics of ralos", "dark bow",
			"sulphur blades", "glacial temotli", "earthbound tecpatl", "infernal tecpatl",
			"torag's hammers", "twinflame staff", "karil's crossbow");
		// Special attacks that hit more than once (claws land over two ticks)
		window(1, "dragon claws", "burning claws", "dragon dagger", "abyssal dagger", "dragon knife",
			"magic shortbow", "webweaver bow", "crystal halberd", "dragon halberd", "dinh's bulwark");
		// Both hits land on the same tick. The Rosewood blowpipe attacks fast, so its normal shots a
		// tick apart must stay separate attacks.
		window(0, "rosewood blowpipe", "saradomin sword");
		// The Bounty Hunter Vesta's spear's second hit lands two ticks after the first
		window(2, "vesta's spear (bh)");
	}

	private MultiHit()
	{
	}

	private static void window(int ticks, String... names)
	{
		for (String name : names)
		{
			WEAPONS.put(name, ticks);
		}
	}

	/**
	 * How many ticks after an attack's first hit its other hits can land, or -1 if this weapon's
	 * hits are always separate attacks. The label may include a spell, e.g. "Twinflame staff (Fire Wave)".
	 */
	static int windowTicks(String weaponLabel)
	{
		String name = weaponLabel.toLowerCase();
		for (Map.Entry<String, Integer> e : WEAPONS.entrySet())
		{
			if (name.contains(e.getKey()))
			{
				return e.getValue();
			}
		}
		return -1;
	}
}

package com.bosshittracker;

/**
 * Your hits during one phase of a multi-stage boss kill.
 */
public class PhaseStats
{
	int hits;
	long damage;
	int maxHit;
	/** When your first hit in this phase landed, used to order phases and time them. */
	long firstHitMs;

	void addHit(int amount, long now)
	{
		if (hits == 0)
		{
			firstHitMs = now;
		}
		hits++;
		damage += amount;
		maxHit = Math.max(maxHit, amount);
	}

	public int getHits()
	{
		return hits;
	}

	public long getDamage()
	{
		return damage;
	}

	public int getMaxHit()
	{
		return maxHit;
	}

	public long getFirstHitMs()
	{
		return firstHitMs;
	}

	void merge(PhaseStats other)
	{
		firstHitMs = hits == 0 ? other.firstHitMs : Math.min(firstHitMs, other.firstHitMs);
		hits += other.hits;
		damage += other.damage;
		maxHit = Math.max(maxHit, other.maxHit);
	}

	PhaseStats copy()
	{
		PhaseStats c = new PhaseStats();
		c.hits = hits;
		c.damage = damage;
		c.maxHit = maxHit;
		c.firstHitMs = firstHitMs;
		return c;
	}
}

package com.bosshittracker;

/**
 * Totals for the hits you landed with one weapon.
 */
public class WeaponStats
{
	int hits;
	int zeros;
	long damage;
	int maxHit;
	/** Attacks made (a multi-hit attack like the Scythe's counts once). 0 for data saved before attacks were counted. */
	int attacks;
	/** Attacks where none of the hits did damage. */
	int missedAttacks;

	void addHit(int amount)
	{
		hits++;
		damage += amount;
		if (amount == 0)
		{
			zeros++;
		}
		if (amount > maxHit)
		{
			maxHit = amount;
		}
	}

	void merge(WeaponStats other)
	{
		hits += other.hits;
		zeros += other.zeros;
		damage += other.damage;
		maxHit = Math.max(maxHit, other.maxHit);
		attacks += other.attacks;
		missedAttacks += other.missedAttacks;
	}

	/** Take away a fight's hits, e.g. when that fight is deleted. The max hit is left as is. */
	void subtract(WeaponStats other)
	{
		hits = Math.max(0, hits - other.hits);
		zeros = Math.max(0, zeros - other.zeros);
		damage = Math.max(0, damage - other.damage);
		attacks = Math.max(0, attacks - other.attacks);
		missedAttacks = Math.max(0, missedAttacks - other.missedAttacks);
	}

	WeaponStats copy()
	{
		WeaponStats c = new WeaponStats();
		c.merge(this);
		return c;
	}

	public int getHits()
	{
		return hits;
	}

	/** Hits that did 0 damage. Since May 2024 a player's successful hit always does at least 1, so these are misses. */
	public int getZeros()
	{
		return zeros;
	}

	public long getDamage()
	{
		return damage;
	}

	public int getMaxHit()
	{
		return maxHit;
	}

	public double getAverageHit()
	{
		return hits == 0 ? 0 : (double) damage / hits;
	}

	/** Share of hits that did damage, 0-100. */
	public double getNonZeroPercent()
	{
		return hits == 0 ? 0 : 100.0 * (hits - zeros) / hits;
	}

	public int getAttacks()
	{
		return attacks;
	}

	public int getMissedAttacks()
	{
		return missedAttacks;
	}

	/** True when this weapon's attacks were counted and some landed as several hits (e.g. the Scythe). */
	public boolean hasMultiHitAttacks()
	{
		return attacks > 0 && attacks != hits;
	}

	/**
	 * Accuracy, 0-100: share of attacks where at least one hit did damage. A multi-hit attack counts
	 * once. For data saved before attacks were counted, the share of hits that did damage.
	 */
	public double getAccuracy()
	{
		return attacks == 0 ? getNonZeroPercent() : 100.0 * (attacks - missedAttacks) / attacks;
	}
}

